const fs=require('fs'),crypto=require('crypto'),assert=require('assert');
const read=p=>fs.readFileSync(p,'utf8');
for(const file of ['assets/debug-economy.js','assets/choco-dig.js','assets/six-candy-rounds-engine.js'])assert(read('index.html').includes(read(file).trim()),'Stale inline module '+file);assert(read('assets/six-candy.js').includes(read('assets/six-candy-rounds-engine.js').trim()));
const html=read('index.html'),src=html.slice(html.indexOf('const SPECIAL_RATE='),html.indexOf('const elixirGlyphs='))+read('assets/choco-dig.js').split('const chocoSprites=')[0]+read('assets/six-candy-rounds-engine.js');
const q=new Function('motionReduced',src+';return {Engine,ChocoDigEngine,sixMakeBoard,sixPickGapTemplate};')(false);
let seed=129871;const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/4294967296);let out=[];
(async()=>{const e=new q.Engine({random});e.wait=async()=>true;for(let i=0;i<30;i++){e.reset();e.running=true;const nums=Array.from({length:25},(_,i)=>i+1);for(let j=24;j>0;j--){let k=Math.floor(random()*(j+1));[nums[k],nums[j]]=[nums[j],nums[k]];}e.queue=[nums.slice(0,3),nums.slice(3,5),...nums.slice(5,8).map(n=>[n])];e.accepted=8;await e.drain();out.push([e.totalHundredths,e.board,e.hammerQueue,e.wonderToken]);}const c=new q.ChocoDigEngine({random});for(let i=0;i<30;i++){const p=c.plan([1,5,9,13,17,21,23,25]);out.push([p.gain,p.grid,p.depth]);c.strata=p.grid;for(const k of ['seed','uid','depth','nextSugar','fruitCount','fruitState','bonusResolvedDepth'])c[k]=p[k];c.phase='complete';c.continueDepth=p.gain>0;c.reset();out.push(q.sixMakeBoard(10,4,random,0,{holes:q.sixPickGapTemplate(random,1)}));}const hash=crypto.createHash('sha256').update(JSON.stringify(out)).digest('hex');assert.equal(hash,'fa8be601746c3fd412c93cd8ecd125528aa03c24c39b2630726f9612fa118fdb','90% generation differs from published v25');
for(const target of [50,70,90,110,130,150]){const a=new Function('motionReduced',src+';debugPayoutTarget='+target+';return {Engine,debugEconomyProfile,debugCookiePotential,chocoOreRates,COOKIE_ALL_CLEAR_HUNDREDTHS,SIX_PAY};')(false);const engine=new a.Engine({random});const before=JSON.stringify(engine.board);a.debugCookiePotential(engine.board,engine.board[0][0].id);assert.equal(JSON.stringify(engine.board),before,'Placement scoring mutated the board');for(const depth of [0,300,350,400,1000]){const rates=a.chocoOreRates(60,depth);assert(Object.values(rates).every(v=>v>=0&&Number.isFinite(v)));assert(Object.values(rates).reduce((n,v)=>n+v,0)<1);}assert.equal(a.COOKIE_ALL_CLEAR_HUNDREDTHS,2000);assert.equal(a.SIX_PAY.allClear,10000);const nums=engine.board.flat().filter(t=>t.number!=null).map(t=>t.number);assert.equal(nums.length,25);assert.equal(new Set(nums).size,25);}
console.log('DEBUG_ECONOMY_RULES_PASS: exact v25 baseline; immutable scoring; 50..150 density bounds and fixed awards');})();
